```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology modelling securities, debt/equity/hybrid instruments, derivatives, investment funds, and the IAS32/IFRS9 accounting classification overlay, derived from a corpus on securities and financial instruments." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "Asset" ;
  rdfs:comment "A generic resource whose performance or value can underlie a derivative or be owned as a financial asset." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (IAS 32: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Cash Instrument" ;
  rdfs:comment "An instrument whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
    )
  ] ;
  rdfs:label "Derivative" ;
  rdfs:comment "An instrument which derives its value from the value and characteristics of one or more underlying entities such as an asset, index, currency, or interest rate. Note: the US SEC passage alternatively treats derivatives as a third broad category of 'securities' alongside debt and equity securities, conflicting with the cash/derivative split used as the primary structure here; both views are reported in the corpus." .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument such as loans, where both borrower and lender must agree on a transfer." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument such as deposits, where both borrower and lender must agree on a transfer." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Index a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset .

#################################################################
# SECURITY
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Security" ;
  rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns and is readily transferable." .

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:entitlesToPrincipalRepayment ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "Debt Security" ;
  rdfs:comment "The holder of a debt security is typically entitled to the payment of principal and interest, together with other contractual rights under the terms of issue." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:entitlesToResidualClaim ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "Equity Security" ;
  rdfs:comment "A share of equity interest in an entity; entitles the holder to a pro rata portion of control and to the residual interest of the issuer after obligations to creditors have been paid." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:entitlesToPrincipalRepayment ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:entitlesToResidualClaim ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "Hybrid Security" ;
  rdfs:comment "Combines some of the characteristics of both debt and equity securities." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity ) ] .

#################################################################
# ISSUER & HOLDER
#################################################################

fis:Issuer a owl:Class ; rdfs:label "Issuer" ;
  rdfs:comment "The company or other entity issuing the security." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganisation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "State, provincial, territorial, municipal or other governmental unit other than a sovereign government." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:SupranationalOrganisation fis:LocalGovernment fis:Corporation ) ] .

fis:Holder a owl:Class ; rdfs:label "Holder" .

fis:Shareholder a owl:Class ;
  rdfs:subClassOf fis:Holder ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Holder
      [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock in a joint stock company." .

fis:Bondholder a owl:Class ;
  rdfs:subClassOf fis:Holder ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Holder
      [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:Bond ] ) ] ;
  rdfs:comment "The creditor to whom the issuer of a bond owes a debt." .

owl:AllDisjointClasses [ owl:members ( fis:Shareholder fis:Bondholder ) ] .

#################################################################
# PAYMENTS
#################################################################

fis:Payment a owl:Class ; rdfs:label "Payment" .

fis:Coupon a owl:Class ; rdfs:subClassOf fis:Payment ;
  rdfs:comment "A fixed, contractually-obligated periodic interest payment paid by a bond issuer to the holder." .

fis:Dividend a owl:Class ; rdfs:subClassOf fis:Payment ;
  rdfs:comment "A discretionary portion of a company's profit paid to shareholders; a company is not legally obliged to declare one, in contrast to a coupon." .

owl:AllDisjointClasses [ owl:members ( fis:Coupon fis:Dividend ) ] .

#################################################################
# BOND
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Bond" ;
  rdfs:comment "Under a bond the issuer (debtor) owes the holder (creditor) a debt and is obliged to provide cash flow, usually repayment of principal at maturity plus interest (coupon)." .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Money Market Instrument" ;
  rdfs:comment "A short-term debt instrument with original maturity of one year or less; certificates of deposit and short-term commercial paper are classified as money market instruments and not as bonds." .

owl:AllDisjointClasses [ owl:members ( fis:Bond fis:MoneyMarketInstrument ) ] .

# --- Bond by issuer ---
fis:GovernmentBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "Government Bond" ; rdfs:comment "Also called a sovereign bond, issued by a sovereign national government." .

fis:SupranationalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganisation ] ) ] ;
  rdfs:label "Supranational Bond" .

fis:MunicipalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
  rdfs:label "Municipal Bond" ; rdfs:comment "Known in the US as a municipal bond (muni); the local-authority bond issued by state, provincial, territorial or municipal governments." .

fis:CorporateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:label "Corporate Bond" .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond ) ] .

# --- Municipal bond subtypes ---
fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest are secured by the full faith and credit of the issuer." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment of principal and interest promised from a specified stream of future income." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment based on property tax assessments of properties within the issuer's boundaries." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond fis:AssessmentBond ) ] .

# --- Bond by coupon structure ---
fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isCouponFixed ; owl:hasValue true ] ) ] ;
  rdfs:comment "Interest payments remain constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isCouponFixed ; owl:hasValue false ] ) ] ;
  rdfs:comment "The coupon varies throughout the life of the bond based on a money-market reference rate." .

fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par value, with the holder receiving the full principal at maturity." .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

# --- Bond by maturity ---
fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasMaturity ; owl:hasValue false ] ) ] ;
  rdfs:label "Perpetual Bond" ; rdfs:comment "A perpetuity; a bond with no maturity date, also called a perp." .

# --- Bond optionality ---
fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] ;
  rdfs:comment "The issuer has the right to repay the bond before the maturity date." .

fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
  rdfs:comment "Also called a retractable bond; the holder may force the issuer to repay before maturity." .

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Lets a bondholder exchange the bond for a number of shares of the issuer's own common stock; a hybrid security." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ]
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Allows exchange into shares of a corporation other than the bond's own issuer." .

owl:AllDisjointClasses [ owl:members ( fis:ConvertibleBond fis:ExchangeableBond ) ] .

# --- Bond registration ---
fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isRegistered ; owl:hasValue false ] ) ] ;
  rdfs:comment "An official certificate issued without a named holder; claimable by whoever holds it." .

fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isRegistered ; owl:hasValue true ] ) ] ;
  rdfs:comment "Ownership is recorded by the issuer or a transfer agent; the opposite of a bearer bond." .

owl:AllDisjointClasses [ owl:members ( fis:BearerBond fis:RegisteredBond ) ] .

fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond that does not have a paper certificate." .

# --- Bond seniority ---
fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] ;
  rdfs:comment "Has lower priority than senior bonds of the same issuer in case of liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

# --- Bond credit quality ---
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "High grade corporate bond rated AAA, AA, A or BBB." .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Junk bond, rated BB and below; rated below investment grade." .

owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

# --- Securitised / covered bonds ---
fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] ;
  rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets." .

fis:MortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:comment "An asset-backed security secured by a mortgage or collection of mortgages." .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:comment "A structured asset-backed security backed by a pool of debt obligations, sliced into tranches." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:disjointWith fis:AssetBackedSecurity ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." .

# --- Money market instruments ---
fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." .
fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a specific fixed term." .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A zero-coupon short-term debt obligation of a national government maturing in one year or less." .

owl:AllDisjointClasses [ owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:TreasuryBill ) ] .

#################################################################
# EQUITY
#################################################################

fis:Stock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "Stock" ;
  rdfs:comment "Also called a share; a unit by which ownership of a corporation is divided, giving fractional ownership." .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRights ; owl:hasValue true ] ) ] ;
  rdfs:comment "Carries voting rights exercised in corporate decisions; also called ordinary or voting share." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendPriority ; owl:hasValue true ] ) ] ;
  rdfs:comment "Senior to common stock, subordinate to bonds, with priority in dividend payments and liquidation; generally considered a hybrid instrument. CONFLICT: one passage classifies preference shares as a distinct hybrid/intermediate security between equity and debt, while another classifies preferred stock as a type of stock (equity security); both views are retained via multiple superclasses." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Preferred stock that includes the ability of the holder to convert into a fixed number of common shares." .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue true ] ) ] ;
  rdfs:comment "Requires missed dividends to be paid later before any common-stock dividend." .

fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue false ] ) ] ;
  rdfs:comment "Also called straight preferred; passed dividends are lost if not declared." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "A negotiable instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "Depositary receipt listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract, e.g. swaps, futures, forwards." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .

owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
    [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
    [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] ;
  rdfs:comment "A standardized contract written by a clearing house, operating on an exchange, to buy or sell an asset on a future date at a price agreed today." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
    [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event on a reference entity." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "buy" ] ) ] ;
  rdfs:comment "Conveys the right to buy at a fixed price." .

fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "sell" ] ) ] ;
  rdfs:comment "Conveys the right to sell at a fixed price." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "american" ] ) ] ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "european" ] ) ] ;
  rdfs:comment "May only be exercised on the expiry date." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption ) ] .

fis:StockOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] .

fis:StockFuture a owl:Class ; rdfs:subClassOf fis:Future ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] .

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:Option, fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "An option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds and separately tradeable." .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Investment Fund" ;
  rdfs:comment "Pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "An SEC-registered open-end investment company; shares bought/sold at net asset value." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Shares trade on national securities exchanges at market prices that may differ from net asset value, unlike mutual funds." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools investor money but is subject to far fewer regulations than a mutual fund." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:Bond ] ) ] .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Invests across both equity and fixed-income securities." .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "A passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Seeks to outperform market indices but generally charges higher fees; over long durations passively managed funds consistently outperform actively managed funds." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

#################################################################
# IAS 32 / IFRS 9 ACCOUNTING OVERLAY
#################################################################

fis:ContractualRight a owl:Class .
fis:RightToReceiveCash a owl:Class ; rdfs:subClassOf fis:ContractualRight .
fis:RightToExchangeFavourable a owl:Class ; rdfs:subClassOf fis:ContractualRight .

fis:ContractualObligation a owl:Class .
fis:ObligationToDeliverCash a owl:Class ; rdfs:subClassOf fis:ContractualObligation .
fis:ObligationToExchangeUnfavourable a owl:Class ; rdfs:subClassOf fis:ContractualObligation .

fis:EquityInstrument a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialInstrument
    [ a owl:Restriction ; owl:onProperty fis:isResidualInterestIn ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. Broader than EquitySecurity: classification depends on contractual substance, not the instrument's label (e.g. a mandatorily redeemable preference share is classified as a financial liability, not equity, under this test)." .

fis:EquitySecurity rdfs:subClassOf fis:EquityInstrument .

fis:Cash a owl:Class ; rdfs:subClassOf fis:Asset .

fis:FinancialAsset a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:unionOf (
      fis:Cash
      fis:EquityInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasContractualRight ; owl:someValuesFrom fis:RightToReceiveCash ]
      [ a owl:Restriction ; owl:onProperty fis:hasContractualRight ; owl:someValuesFrom fis:RightToExchangeFavourable ]
    ) ] ;
  rdfs:comment "IAS 32: cash, a contractual right to receive cash or another financial instrument, a contractual right to exchange financial instruments under potentially favourable conditions, or an equity instrument of another entity." .

fis:FinancialLiability a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:unionOf (
      [ a owl:Restriction ; owl:onProperty fis:hasContractualObligation ; owl:someValuesFrom fis:ObligationToDeliverCash ]
      [ a owl:Restriction ; owl:onProperty fis:hasContractualObligation ; owl:someValuesFrom fis:ObligationToExchangeUnfavourable ]
    ) ] ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset, or to exchange financial instruments under potentially unfavourable conditions." .

fis:MeasurementCategory a owl:Class .
fis:AmortisedCost a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ;
  rdfs:comment "IFRS 9: applies when held to collect contractual cash flows and those cash flows are solely payments of principal and interest (the SPPI test)." .
fis:FairValueThroughOCI a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ;
  rdfs:comment "IFRS 9: applies when held both to collect contractual cash flows and to sell, and the SPPI test is met." .
fis:FairValueThroughProfitOrLoss a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ;
  rdfs:comment "IFRS 9: default category; applies to derivatives and equity investments and to assets failing the SPPI test or business-model tests." .

owl:AllDisjointClasses [ owl:members ( fis:AmortisedCost fis:FairValueThroughOCI fis:FairValueThroughProfitOrLoss ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:label "hasIssuer" .

fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Holder .

fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ; rdfs:range fis:Asset ;
  rdfs:label "hasUnderlying" .

fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:Derivative .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Asset .

fis:isCollateralOf a owl:ObjectProperty ; owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ; rdfs:range fis:Security .

fis:hasConversionTarget a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:EquitySecurity .

fis:isConversionTargetOf a owl:ObjectProperty ; owl:inverseOf fis:hasConversionTarget ;
  rdfs:domain fis:EquitySecurity ; rdfs:range fis:Security .

fis:hasEmbeddedOption a owl:ObjectProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:Option .

fis:isEmbeddedOptionOf a owl:ObjectProperty ; owl:inverseOf fis:hasEmbeddedOption ;
  rdfs:domain fis:Option ; rdfs:range fis:Bond .

fis:hasReferenceEntity a owl:ObjectProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer .

fis:isReferenceEntityOf a owl:ObjectProperty ; owl:inverseOf fis:hasReferenceEntity ;
  rdfs:domain fis:Issuer ; rdfs:range fis:CreditDefaultSwap .

fis:hasPortfolio a owl:ObjectProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range fis:FinancialInstrument .

fis:isPortfolioOf a owl:ObjectProperty ; owl:inverseOf fis:hasPortfolio ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:InvestmentFund .

fis:hasContractualRight a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:ContractualRight .

fis:isContractualRightOf a owl:ObjectProperty ; owl:inverseOf fis:hasContractualRight ;
  rdfs:domain fis:ContractualRight ; rdfs:range fis:FinancialInstrument .

fis:hasContractualObligation a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:ContractualObligation .

fis:isContractualObligationOf a owl:ObjectProperty ; owl:inverseOf fis:hasContractualObligation ;
  rdfs:domain fis:ContractualObligation ; rdfs:range fis:FinancialInstrument .

fis:isResidualInterestIn a owl:ObjectProperty ;
  rdfs:domain fis:EquityInstrument ; rdfs:range fis:Corporation .

fis:hasResidualInterestOf a owl:ObjectProperty ; owl:inverseOf fis:isResidualInterestIn ;
  rdfs:domain fis:Corporation ; rdfs:range fis:EquityInstrument .

fis:hasMeasurementCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:MeasurementCategory .

fis:isMeasurementCategoryOf a owl:ObjectProperty ; owl:inverseOf fis:hasMeasurementCategory ;
  rdfs:domain fis:MeasurementCategory ; rdfs:range fis:FinancialAsset .

fis:hasCoupon a owl:ObjectProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:Coupon .

fis:isCouponOf a owl:ObjectProperty ; owl:inverseOf fis:hasCoupon ;
  rdfs:domain fis:Coupon ; rdfs:range fis:Bond .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:Stock ; rdfs:range fis:Dividend .

fis:isDividendOf a owl:ObjectProperty ; owl:inverseOf fis:hasDividend ;
  rdfs:domain fis:Dividend ; rdfs:range fis:Stock .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "hasFaceValue" ;
  rdfs:comment "Also called par value, principal, or nominal amount." .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:date .

fis:hasMaturity a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ;
  rdfs:comment "True unless the bond is perpetual (no maturity date)." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasIssueDate a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:date .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
