```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology modeling securities, debt, equity, hybrid and derivative financial instruments, investment funds, and related roles, built from a corpus of finance reference texts (Wikipedia, SEC/FINRA, IAS/IFRS, BIS, ECB, OpenStax, CFI)." .

#################################################################
# TOP LEVEL
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "Asset" ;
  rdfs:comment "Generic top class for anything of value, including financial instruments, commodities, real estate and reference variables." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled. Per IAS 32/39: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:CashInstrument a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument whose value is determined directly by the markets; includes securities, loans and deposits." .

fis:Derivative a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Derivative" , "Derivative instrument" ;
  rdfs:comment "A contract whose value derives from the value of one or more underlying assets, rates or indices. NOTE: the corpus also states (US law) that derivatives can be classified as a category of 'security' alongside debt and equity securities, while other passages place derivatives outside the cash-instrument/security family. This ontology follows the majority structural statement that financial instruments are either cash instruments or derivatives." .

fis:FinancialInstrument owl:equivalentClass [
  a owl:Class ; owl:unionOf ( fis:CashInstrument fis:Derivative )
] .

fis:CashInstrument owl:disjointWith fis:Derivative .

fis:Security a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A tradable financial asset. US law: a tradable financial asset of any kind, broadly debt, equity or derivatives. UK FCA Handbook restricts 'security' to a narrower enumerated list (equities, debentures, government/public securities, warrants, units, etc.), excluding most derivatives - a jurisdictional conflict noted here rather than resolved." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument such as a loan or deposit where borrower and lender must agree to any transfer." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:HomeEquityLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:Asset .

fis:Index a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "A price index or market index such as a stock market index or bond market index." .
fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset .
fis:RealEstateAsset a owl:Class ; rdfs:subClassOf fis:Asset .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Security fis:Loan fis:Deposit ) .

#################################################################
# AGENT / ROLE CLASSES
#################################################################

fis:Issuer a owl:Class ;
  rdfs:comment "The company or other entity issuing a security or financial instrument." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "State, provincial, territorial or municipal governmental unit other than a sovereign government." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "An international organization such as the World Bank or IMF." .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Corporation .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:Corporation fis:SupranationalOrganization ) .

fis:Investor a owl:Class ;
  rdfs:comment "A natural or legal person investing in securities." .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Member of the public investing personally, other than by way of business." .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Financial institution acting on its own account or on behalf of clients (wholesale investor)." .
[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) .

fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:label "Stockholder" ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "The creditor holder of a bond, entitled to payment of principal and interest." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the instrument." .
fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ; rdfs:domain fis:Security ; rdfs:range fis:Investor .
fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasShareholder a owl:ObjectProperty ; rdfs:subPropertyOf fis:hasHolder ;
  rdfs:domain fis:Stock ; rdfs:range fis:Shareholder .
fis:isShareholderOf a owl:ObjectProperty ; owl:inverseOf fis:hasShareholder ;
  rdfs:subPropertyOf fis:isHolderOf ; rdfs:domain fis:Shareholder ; rdfs:range fis:Stock .

fis:hasBondholder a owl:ObjectProperty ; rdfs:subPropertyOf fis:hasHolder ;
  rdfs:domain fis:Bond ; rdfs:range fis:Bondholder .
fis:isBondholderOf a owl:ObjectProperty ; owl:inverseOf fis:hasBondholder ;
  rdfs:subPropertyOf fis:isHolderOf ; rdfs:domain fis:Bondholder ; rdfs:range fis:Bond .

fis:hasUnderlying a owl:ObjectProperty ; rdfs:domain fis:Derivative ; rdfs:range fis:Asset ;
  rdfs:comment "The item (underlier) a derivative's value depends on: a commodity, a financial instrument, a price index, a currency, or an interest rate. Also used for convertible instruments' conversion target." .
fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:Derivative .

fis:hasCollateral a owl:ObjectProperty ; rdfs:domain fis:AssetBackedSecurity ; rdfs:range fis:Asset .
fis:isCollateralOf a owl:ObjectProperty ; owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ; rdfs:range fis:AssetBackedSecurity .

fis:hasCreditRating a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:CreditRating .
fis:isCreditRatingOf a owl:ObjectProperty ; owl:inverseOf fis:hasCreditRating ;
  rdfs:domain fis:CreditRating ; rdfs:range fis:DebtSecurity .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer ;
  rdfs:comment "The reference entity whose debt underlies a credit default swap." .
fis:isReferenceEntityOf a owl:ObjectProperty ; owl:inverseOf fis:hasReferenceEntity ;
  rdfs:domain fis:Issuer ; rdfs:range fis:CreditDefaultSwap .

fis:hasDividend a owl:ObjectProperty ; rdfs:domain fis:Stock ; rdfs:range fis:Dividend .
fis:isDividendOf a owl:ObjectProperty ; owl:inverseOf fis:hasDividend ;
  rdfs:domain fis:Dividend ; rdfs:range fis:Stock .

fis:hasTradingVenue a owl:ObjectProperty ; rdfs:domain fis:FinancialInstrument ; rdfs:range fis:TradingVenue .
fis:isTradingVenueOf a owl:ObjectProperty ; owl:inverseOf fis:hasTradingVenue ;
  rdfs:domain fis:TradingVenue ; rdfs:range fis:FinancialInstrument .

fis:hasMeasurementCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:MeasurementCategory ;
  rdfs:comment "IFRS 9 subsequent-measurement classification of a financial asset." .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:date ;
  rdfs:comment "The issuer is obligated to repay the nominal amount on this single maturity date." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "par value" , "principal amount" , "nominal amount" .

fis:hasParValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:decimal ;
  rdfs:comment "A nominal accounting value of a share; shares may also be issued without par value." .

fis:hasCouponRate a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate that the issuer pays to the holder; may be fixed, floating, or zero." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date .

fis:hasPremium a owl:DatatypeProperty ; rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty ; rdfs:domain fis:Swap ; rdfs:range xsd:decimal ;
  rdfs:comment "Underlying principal used to calculate swap cash flows; usually not exchanged." .

fis:hasISIN a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string .

fis:hasTickerSymbol a owl:DatatypeProperty ; rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:hasResidualClaimStatus a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the security confers only a residual claim on issuer assets/profits after creditors are paid (equity); false if it carries a fixed contractual claim (debt)." .

fis:hasObligationToTransact a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:boolean ;
  rdfs:comment "True for lock products (forward, future, swap) which obligate both parties; false for option products which give a right but not an obligation." .

fis:hasExchangeTradedStatus a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:boolean .

fis:hasStandardizationStatus a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:boolean .

fis:hasSecuredStatus a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean ;
  rdfs:comment "True if backed by collateral; false if unsecured (debenture/commercial paper)." .

fis:hasCallProvision a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasPutProvision a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasOptionRight a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
  rdfs:comment "'call' (right to buy) or 'put' (right to sell)." .

#################################################################
# SECURITY FORM / PROPRIETARY-NATURE CLASSES
#################################################################

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Non-certificated / electronic 'book entry only' security." .
[] a owl:AllDisjointClasses ; owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) .

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:comment "Entitles the holder to rights merely by holding the instrument; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:comment "Entitles the holder to rights only if they appear on a security register." .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each instrument constitutes a separate asset/covenant, legally distinct from other securities in the same issue." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue is one asset; each security is a fractional part of that whole." .
[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "All holdings of the security are treated identically and interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
[] a owl:AllDisjointClasses ; owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) .

#################################################################
# MARKET / OFFERING
#################################################################

fis:TradingVenue a owl:Class .
fis:Exchange a owl:Class ; rdfs:subClassOf fis:TradingVenue ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:TradingVenue .
[] a owl:AllDisjointClasses ; owl:members ( fis:Exchange fis:OverTheCounterMarket ) .

fis:Market a owl:Class .
fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "The market for new securities, where the issuer receives the sale proceeds." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "The market for already-issued securities trading between investors." .
[] a owl:AllDisjointClasses ; owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) .

fis:Offering a owl:Class .
fis:PublicOffering a owl:Class ; rdfs:subClassOf fis:Offering .
fis:PrivatePlacement a owl:Class ; rdfs:subClassOf fis:Offering ;
  rdfs:comment "Offered privately to a limited number of qualified investors; not publicly tradable." .
[] a owl:AllDisjointClasses ; owl:members ( fis:PublicOffering fis:PrivatePlacement ) .

#################################################################
# DEBT / EQUITY TOP SPLIT
#################################################################

fis:DebtSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasResidualClaimStatus ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
  rdfs:comment "Holder entitled to payment of principal and interest; debt securities may be called debentures, bonds, deposits, notes or commercial paper." .

fis:EquitySecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasResidualClaimStatus ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
  rdfs:comment "A share of equity interest in an entity; entitled only to the residual interest after creditors are paid, but to pro-rata control and profit upside." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines characteristics of both debt and equity securities (e.g. preference shares, convertibles, equity warrants). Not disjoint with DebtSecurity/EquitySecurity since specific instruments (preferred stock, convertible bonds) are simultaneously hybrid and legally debt or equity." .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity ) .

#################################################################
# BOND
#################################################################

fis:Bond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Issuer ]
      [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ]
  ) ] ;
  rdfs:comment "Issuer (debtor) owes the holder (creditor) a debt and must repay the principal at the maturity date, usually with coupon interest." .

fis:GovernmentBond a owl:Class ;
  rdfs:label "sovereign bond" , "treasury bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Strictly applies only to bonds issued by corporations; supranational and municipal bonds are excluded." .

fis:MunicipalBond a owl:Class ;
  rdfs:label "muni" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:SupranationalBond a owl:Class ;
  rdfs:label "supra" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:CorporateBond fis:MunicipalBond fis:SupranationalBond ) .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Issued by a government to fund military operations during wartime." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a government or corporate entity to raise finance for climate mitigation/adaptation projects." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Secured by the full faith and credit of the issuer and its taxing power." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repaid solely from a specified revenue stream; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments; generally a form of general obligation bond." .
[] a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) .

fis:TreasurySecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US government bond issued by the US Department of the Treasury." .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:TreasurySecurity .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:TreasurySecurity .
fis:TreasuryBondUS a owl:Class ; rdfs:label "T-bond" ; rdfs:subClassOf fis:TreasurySecurity .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:TreasurySecurity .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK government bond." .
fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:Gilt .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:Gilt .

fis:MortgageBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond secured by the pledge of specific assets, such as a pool of mortgages on real estate." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

fis:Debenture a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSecuredStatus ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
  rdfs:comment "Unsecured bond; long maturity, typically at least ten years." .
fis:Note a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Debt security with shorter maturity than a debenture." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "floater" .
fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:label "discount bond" , "deep discount bond" .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "linker" .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond .
[] a owl:AllDisjointClasses ; owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) .

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BearerSecurity .
fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:RegisteredSecurity .
fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:NonCertificatedSecurity .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) .

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCallProvision ; owl:hasValue "true"^^xsd:boolean ] ) ] .
fis:PutableBond a owl:Class ;
  rdfs:label "retractable bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasPutProvision ; owl:hasValue "true"^^xsd:boolean ] ) ] .
fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .
[] a owl:AllDisjointClasses ; owl:members ( fis:CallableBond fis:PutableBond fis:BulletBond ) .

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Lower priority than senior bonds of the issuer in liquidation." .
[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorBond fis:SubordinatedBond ) .

fis:ShortTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:MediumTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:LongTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "perpetuity" , "consol" ;
  rdfs:comment "Has no maturity date." .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:ShortTermBond fis:MediumTermBond fis:LongTermBond fis:PerpetualBond ) .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets which remain on the issuer's balance sheet." .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "junk bond" .
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond .
[] a owl:AllDisjointClasses ; owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) .

#################################################################
# CONVERTIBLE / EXCHANGEABLE
#################################################################

fis:ConvertibleSecurity a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "A security convertible, at the holder's election, into another security (typically common stock)." .

fis:ConvertibleBond a owl:Class ;
  rdfs:label "convertible note" , "convertible debenture" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:ConvertibleSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "A bond the holder can convert into a specified number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:ConvertibleSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

[] a owl:AllDisjointClasses ; owl:members ( fis:ConvertibleBond fis:ExchangeableBond ) .

#################################################################
# MONEY MARKET
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short-term debt instrument with original maturity of one year or less." .

fis:CommercialPaper a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasSecuredStatus ; owl:hasValue "false"^^xsd:boolean ]
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Unsecured promissory note with a fixed maturity of usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ] ) ] ;
  rdfs:comment "A time deposit sold by banks, thrift institutions, and credit unions." .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price and date." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

fis:TreasuryBill rdfs:subClassOf fis:MoneyMarketInstrument, fis:ZeroCouponBond .

fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Securities issued internationally outside their domestic market in a denomination different from the issuer's domicile." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:Bond ;
  rdfs:comment "Characteristically underwritten, unsecured, with interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity .
fis:EuroCommercialPaper a owl:Class ; rdfs:subClassOf fis:Euronote, fis:CommercialPaper .
fis:EuroCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:Euronote, fis:CertificateOfDeposit .

#################################################################
# ASSET-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
  rdfs:label "ABS" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] ;
  rdfs:comment "Bond backed by a pool of assets such as loans, leases or receivables." .

fis:MortgageBackedSecurity a owl:Class ;
  rdfs:label "MBS" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:label "RMBS" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:label "CMBS" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:label "CMO" , "pay-through bond" ;
  rdfs:subClassOf fis:MortgageBackedSecurity .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:label "SMBS" ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:InterestOnlyStrippedMortgageBackedSecurity a owl:Class ; rdfs:label "IO strip" ;
  rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrippedMortgageBackedSecurity a owl:Class ; rdfs:label "PO strip" ;
  rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:NetInterestMarginSecurity a owl:Class ; rdfs:label "NIMS" ; rdfs:subClassOf fis:MortgageBackedSecurity .
[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrippedMortgageBackedSecurity fis:PrincipalOnlyStrippedMortgageBackedSecurity ) .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:label "CDO" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
  rdfs:comment "Sliced into tranches catching cash flow in sequence of seniority." .

fis:HomeEquityLoanBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:AutoLoanBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:CreditCardBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:StudentLoanBackedSecurity a owl:Class ; rdfs:label "SLABS" ; rdfs:subClassOf fis:AssetBackedSecurity .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:HomeEquityLoanBackedSecurity fis:AutoLoanBackedSecurity fis:CreditCardBackedSecurity fis:StudentLoanBackedSecurity ) .

#################################################################
# EQUITY: STOCK
#################################################################

fis:Stock a owl:Class ;
  rdfs:label "share" , "capital stock" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Consists of all the shares by which ownership of a corporation or company is divided (also applies to trusts and partnerships)." .

fis:CommonStock a owl:Class ; rdfs:label "ordinary share" , "equity share" ;
  rdfs:subClassOf fis:Stock ;
  rdfs:comment "Carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ; rdfs:label "preference share" , "preferred share" ;
  rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  rdfs:comment "Senior to common stock, subordinate to bonds; priority on dividends and liquidation; generally no voting rights." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock, fis:ConvertibleSecurity .
fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate as dividends in arrears." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "straight preferred stock" .
[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .
fis:CallablePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock .

fis:Dividend a owl:Class ; rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, unlike a bond coupon." .
fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
[] a owl:AllDisjointClasses ; owl:members ( fis:CashDividend fis:StockDividend ) .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ; rdfs:label "DR" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "Negotiable instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:label "ADR" ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:label "EDR" ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:label "GDR" ; rdfs:subClassOf fis:DepositaryReceipt .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasObligationToTransact ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (swaps, futures, forwards)." .

fis:OptionProduct a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasObligationToTransact ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under specified terms (options, warrants)." .

[] a owl:AllDisjointClasses ; owl:members ( fis:LockProduct fis:OptionProduct ) .

fis:Forward a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
      [ a owl:Restriction ; owl:onProperty fis:hasExchangeTradedStatus ; owl:hasValue "false"^^xsd:boolean ]
      [ a owl:Restriction ; owl:onProperty fis:hasStandardizationStatus ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
  rdfs:comment "Non-standardized, privately negotiated OTC contract to buy/sell at a future date at today's agreed price." .

fis:Future a owl:Class ;
  rdfs:label "futures contract" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
      [ a owl:Restriction ; owl:onProperty fis:hasExchangeTradedStatus ; owl:hasValue "true"^^xsd:boolean ]
      [ a owl:Restriction ; owl:onProperty fis:hasStandardizationStatus ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
  rdfs:comment "Standardized exchange-traded contract written by a clearing house, marked to market daily. NOTE: BIS classifies only three basic derivative types (forward, swap, option), treating the future as a standardized/exchange-traded sub-case of the forward; this ontology follows the majority four-type classification (forward, future, option, swap)." .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's." .
fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "cross-currency swap" .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:label "CDS" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:comment "Seller compensates buyer in the event of default or other credit event on a reference loan/entity." .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CommoditySwap fis:EquitySwap fis:CreditDefaultSwap ) .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "Right, but not the obligation, to buy or sell an underlying asset at a strike price on or before a specified date." .

fis:CallOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "call" ] ) ] .
fis:PutOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "put" ] ) ] .
[] a owl:AllDisjointClasses ; owl:members ( fis:CallOption fis:PutOption ) .

fis:StockOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .
[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset time period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Underlying price must pass a barrier level before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "All-or-nothing payoff." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "Long-dated option, generally traded over the counter." .
fis:EquityWarrant a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Warrant fis:HybridSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:comment "Issued by the company, allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

fis:OTCDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasExchangeTradedStatus ; owl:hasValue "false"^^xsd:boolean ] ) ] .
fis:ExchangeTradedDerivative a owl:Class ; rdfs:label "ETD" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasExchangeTradedStatus ; owl:hasValue "true"^^xsd:boolean ] ) ] .
[] a owl:AllDisjointClasses ; owl:members ( fis:OTCDerivative fis:ExchangeTradedDerivative ) .

#################################################################
# CREDIT RATING
#################################################################

fis:CreditRating a owl:Class ;
  rdfs:comment "A grade assigned by a rating agency indicating the credit quality of a debt security." .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRating ; rdfs:label "non-investment grade" , "junk" , "speculative grade" .
[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeRating fis:HighYieldRating ) .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Pools money from many investors to purchase stocks, bonds, or other securities; shares represent a proportional interest in the whole portfolio." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "SEC-registered open-end investment company; shares bought/sold at next-calculated net asset value." .
fis:ExchangeTradedFund a owl:Class ; rdfs:label "ETF" ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Shares trade on national securities exchanges at market prices that may be a premium or discount to net asset value." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools investor money but, unlike a mutual fund, is lightly regulated and may use leverage and short selling." .
[] a owl:AllDisjointClasses ; owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Purchased from/sold to the issuer at net asset value; new investors may join at any time." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
[] a owl:AllDisjointClasses ; owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Invests in liquid, short-term debt securities." .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "income fund" .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "stock fund" .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Blends equity and fixed-income investments." .
[] a owl:AllDisjointClasses ; owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:HybridFund ) .

fis:IndexFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Index ] ) ] ;
  rdfs:comment "Passively managed fund designed to track the performance of a particular market index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Seeks to outperform an index through active security selection; charges higher fees." .
[] a owl:AllDisjointClasses ; owl:members ( fis:IndexFund fis:ActivelyManagedFund ) .

#################################################################
# ACCOUNTING (IAS 32 / IFRS 9) VIEW
#################################################################

fis:FinancialAsset a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset, or to exchange financial instruments under potentially unfavourable conditions. The same instrument (e.g. a bond) is a FinancialAsset for the holder and gives rise to a FinancialLiability for the issuer." .

[] a owl:AllDisjointClasses ; owl:members ( fis:FinancialAsset fis:FinancialLiability ) .

fis:MeasurementCategory a owl:Class ;
  rdfs:comment "IFRS 9 subsequent-measurement classification of a financial asset, determined by business model and contractual cash flow (SPPI) tests." .
fis:AmortisedCostMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueOCIMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "FVOCI" .
fis:FairValueProfitOrLossMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "FVTPL" ;
  rdfs:comment "Mandatory category for derivatives and, by default, for equity investments and any asset failing the amortised-cost or FVOCI conditions." .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmortisedCostMeasurement fis:FairValueOCIMeasurement fis:FairValueProfitOrLossMeasurement ) .
